export const meta = {
  "slug": "lucide-settings",
  "family": "lucide",
  "name": "settings",
  "category": "Interface",
  "motion": "gear",
  "component": "createLucideSettingsIcon"
};

export function createLucideSettingsIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
